<?php
require_once __DIR__.'/../includes/security.php';require __DIR__.'/../includes/db.php';if(admin_user()){header('Location: index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){admin_login_check();$ip=$_SERVER['REMOTE_ADDR']??'';$q=$pdo->prepare('SELECT COUNT(*) FROM admin_login_attempts WHERE ip_address=? AND attempted_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE) AND succeeded=0');$q->execute([$ip]);if((int)$q->fetchColumn()>=8){http_response_code(429);$error='Terlalu banyak percobaan. Coba kembali 15 menit lagi.';}else{$u=trim($_POST['username']??'');$pw=$_POST['password']??'';$q=$pdo->prepare('SELECT id,username,password_hash,active FROM admin_users WHERE username=? LIMIT 1');$q->execute([$u]);$row=$q->fetch();$ok=$row&&$row['active']&&password_verify($pw,$row['password_hash']);$pdo->prepare('INSERT INTO admin_login_attempts(ip_address,username,succeeded) VALUES(?,?,?)')->execute([$ip,substr($u,0,100),$ok?1:0]);if($ok){session_regenerate_id(true);unset($_SESSION['admin_login_csrf']);$_SESSION['admin']=['id'=>(int)$row['id'],'username'=>$row['username']];$pdo->prepare('UPDATE admin_users SET last_login=NOW() WHERE id=?')->execute([$row['id']]);admin_event($pdo,'login',null,'Login berhasil');header('Location: index.php');exit;}$error='Nama pengguna atau kata sandi tidak valid.';}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login admin — TokoKita</title><link rel="stylesheet" href="../assets/style.css"><style>body{background:#f5f4ed}.login{max-width:420px;margin:9vh auto;padding:30px}.login h1{font:700 26px Manrope;margin:10px 0}.login .field{margin:14px 0}</style></head><body><form class="panel login" method="post"><a class="brand" href="../index.php"><span class="brand-icon">K</span> toko<span>kita</span></a><h1>Masuk sebagai admin</h1><p class="muted">Gunakan akun administrator toko.</p><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><input type="hidden" name="login_csrf" value="<?=e(admin_login_form_token())?>"><div class="field"><label>Nama pengguna</label><input name="username" required maxlength="100" autocomplete="username"></div><div class="field"><label>Kata sandi</label><input type="password" name="password" required autocomplete="current-password"></div><button class="btn full">Masuk</button><p><a href="forgot-password.php">Lupa kata sandi?</a></p></form></body></html>